using System;using System.Data;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Text;
class AccessProbe {
static int checks; static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
[STAThread]static void Main(string[] args){Console.OutputEncoding=Encoding.UTF8;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var a=Assembly.LoadFrom(args[0]);var flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static;a.GetType("project_fo_3.AppFonts").GetMethod("Initialize",flags,null,Type.EmptyTypes,null).Invoke(null,null);
using(var f=(Form)Activator.CreateInstance(a.GetType("project_fo_3.ManufacturerUiAutomationPreview"),BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{false},null)){
a.GetType("project_fo_3.ResponsiveLayoutSelfTests").GetMethod("SavePreview",flags).Invoke(null,new object[]{f,new Size(1200,800),args[1],"candidate-rows"});var t=(AntdUI.Table)f.Controls.Find("manufacturerTable",true)[0];var source=(DataTable)t.DataSource;var access=t.AccessibilityObject;Check(access.GetChildCount()==3,"header and two real rows");Check(access.GetChild(-1)==null&&access.GetChild(3)==null,"invalid rows rejected");
for(int i=0;i<3;i++){var row=access.GetChild(i);Check(row.GetChildCount()==4,"four cells row "+i);for(int c=0;c<4;c++){var cell=row.GetChild(c);var col=t.Columns[c];string expected=i==0?col.Title:Convert.ToString(source.Rows[i-1][col.Key]);Check(cell.Value==expected,"exact raw "+i+" "+col.Key+" "+expected);Check(cell.Bounds==t.RectangleToScreen(Rectangle.Intersect(t.ClientRectangle,t.CellRectangle(i,c))),"rendered bounds "+i+" "+c);Check((cell.State&AccessibleStates.ReadOnly)!=0,"read only "+i+" "+c);}}
var cachedRow=access.GetChild(1);var cachedCell=cachedRow.GetChild(0);bool rejected=false;try{cachedCell.Value="changed";}catch(InvalidOperationException){rejected=true;}Check(rejected,"write rejected");Check(source.Rows[0][t.Columns[0].Key].ToString()==cachedCell.Value,"write preserved source");
var guard=t.GetType().GetProperty("ReadContextIsCurrent",BindingFlags.Instance|BindingFlags.NonPublic);guard.SetValue(t,new Func<bool>(()=>false),null);Check(access.GetChildCount()==0&&cachedRow.Name==""&&cachedCell.Value==""&&cachedCell.Bounds.IsEmpty,"session denied hides cached values and bounds");guard.SetValue(t,new Func<bool>(()=>true),null);Check(cachedCell.Value!="","current context restores same data");int calls=0;guard.SetValue(t,new Func<bool>(()=>++calls==1),null);Check(cachedCell.Value=="","context revoked during read hides result");guard.SetValue(t,new Func<bool>(()=>true),null);
t.DataSource=source.Copy();Application.DoEvents();Check(cachedRow.GetChildCount()==0&&cachedCell.Name==""&&cachedCell.Bounds.IsEmpty,"rebind invalidates cached objects");Check(access.GetChild(1).GetChild(0).Value==source.Rows[0][t.Columns[0].Key].ToString(),"new source readable");t.Dispose();Check(access.GetChildCount()==0&&cachedCell.Value=="","dispose hides values");Console.WriteLine("CHECKS="+checks);
}}}
